#!/usr/bin/env node
// Node.js ESM port of /workspace/dataset/test19.py — 5-phase markdown pipeline
// with 9 printed results, byte-identical to the reference executable.

import { basename } from 'node:path';
import { parseArgs } from './lib/argparse.mjs';
import { markdown } from './lib/markdown.mjs';
import { highlightCode } from './lib/highlight/index.mjs';

function main() {
  const prog = basename(process.argv[1] || 'test19.mjs');
  const args = parseArgs(process.argv.slice(2), prog);

  // Phase 1: Basic conversions
  const phase1_a = markdown(args.a);
  const phase1_b = markdown(args.b);
  const phase1_c = markdown(args.c);

  // Phase 2: With extensions
  const phase2_d = markdown(args.d, { extensions: ['extra', 'tables'] });
  const phase2_e = markdown(args.e, {
    extensions: ['codehilite', 'fenced_code'],
    highlight: highlightCode,
  });
  const phase2_f = markdown(args.f, { extensions: ['toc'] });

  // Phase 3: Combined processing (exact f-string template from test19.py,
  // including its leading and trailing newlines)
  const phase3_combined = markdown(`
# Combined Document

## Section A
${phase1_a}

## Section B
${phase1_b}

## Section C
${phase1_c}

## Section D
${phase2_d}

## Section E
${phase2_e}

## Section F
${phase2_f}
`);

  // Phase 4: Nested transformations
  const phase4_nested = markdown(`<article>${phase3_combined}</article>`);

  // Phase 5: Final processing with all features
  const phase5_final = markdown(
    args.a + '\n\n' + args.b + '\n\n' + args.c + '\n\n' +
    args.d + '\n\n' + args.e + '\n\n' + args.f,
    {
      extensions: ['extra', 'tables', 'codehilite', 'fenced_code', 'toc'],
      outputFormat: 'xhtml',
      highlight: highlightCode,
    }
  );

  console.log(phase1_a);
  console.log(phase1_b);
  console.log(phase1_c);
  console.log(phase2_d);
  console.log(phase2_e);
  console.log(phase2_f);
  console.log(phase3_combined);
  console.log(phase4_nested);
  console.log(phase5_final);
}

main();

