// Mock markdown engine: records calls, returns a unique marker per call.
import { writeFileSync } from 'node:fs';

const calls = [];

export function markdown(text, options = {}) {
  calls.push({
    text,
    extensions: options.extensions ?? null,
    outputFormat: options.outputFormat ?? null,
    hasHighlight: typeof options.highlight === 'function',
  });
  return `<M${calls.length}>`;
}

export function dumpCalls(path) {
  writeFileSync(path, JSON.stringify(calls, null, 2));
}

