cat > /tmp/fuzz.mjs <<'EOF'
import { execFileSync, spawnSync } from 'node:child_process';

const TOKENS = ['--a','--b','--c','--d','--e','--f','-h','--help','--h','--he','--','-','-5','-5.5','-.5','-5x','--a=x','--b=','--help=1','-h=1','-hx','x','y','--unknown','--unk=v','--=','---','-a','日本語','--a=-h','='];
let seed = 42;
const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;

let pass = 0, fail = 0;
for (let t = 0; t < 600; t++) {
  const n = Math.floor(rnd() * 8);
  const argv = [];
  for (let i = 0; i < n; i++) argv.push(TOKENS[Math.floor(rnd() * TOKENS.length)]);
  const e = spawnSync('/workspace/dataset/test19_executable', argv, { encoding: 'buffer' });
  const m = spawnSync('node', ['/tmp/argtest.mjs', ...argv], { encoding: 'buffer' });
  const ecode = e.status, mcode = m.status;
  let ok;
  if (ecode === 0 && !e.stdout.toString().startsWith('usage:')) {
    // success path: node prints JSON; compare exit + stderr
    ok = mcode === 0 && e.stderr.equals(m.stderr) && m.stderr.length === 0;
  } else {
    ok = ecode === mcode && e.stdout.equals(m.stdout) && e.stderr.equals(m.stderr);
  }
  if (ok) pass++;
  else {
    fail++;
    console.log('FAIL', JSON.stringify(argv), 'ecode=' + ecode, 'mcode=' + mcode);
