export function parseArgs(argv, prog) {
  // argparse classifies every token (up to the first bare "--") via
  // _parse_optional BEFORE consuming anything, so an ambiguous-prefix error
  // fires ahead of help, missing-value, and explicit-argument errors.
  // (Only reachable for tokens like "--=x": "--" prefixes every long option.)
  for (const token of argv) {
    if (token === '--') break;
